console.log("LRU CACHE SIMULATION: Patterns");
function lru(cap, seq){ var cache=[], hits=0; seq.forEach(function(k){ var i=cache.indexOf(k); if(i>=0){ hits++; cache.splice(i,1); } else if(cache.length>=cap){ cache.pop(); } cache.unshift(k); }); return {hits:hits, misses:seq.length-hits}; }
var seq=["a","b","c","a","d","b","a","e","a","b"];
var r=lru(3, seq);
console.log("capacity 3, accesses "+seq.length+": hits="+r.hits+" misses="+r.misses+" hit rate="+(100*r.hits/seq.length).toFixed(1)+"%");
console.log("Recency wins: hot keys stay, cold keys evict.");

